package com.neu.riketiku.demo;

import java.util.List;

/** 每科六道原创综合题，只用于显式本地 Demo 专题学习。 */
final class DemoTopicQuestionBank {
    static final int COUNT_PER_SUBJECT = 6;
    static final int TOTAL_COUNT = 18;

    private DemoTopicQuestionBank() {
    }

    static List<TopicQuestion> questions() {
        return List.of(
                topic("PT-01", "PHYSICS", "力学综合计算", "一质量为\\(2\\,\\mathrm{kg}\\)的小车从静止开始，在水平恒力作用下沿光滑轨道运动。前\\(4\\,\\mathrm{s}\\)内位移为\\(16\\,\\mathrm{m}\\)，随后撤去恒力并进入粗糙水平面，动摩擦因数为\\(\\mu=0.20\\)，取\\(g=10\\,\\mathrm{m/s^2}\\)。求恒力大小、撤力瞬间速度以及小车在粗糙面上的滑行距离。", "力学>运动和力>牛顿运动定律", 3,
                        "步骤1：前4 s做匀加速运动，由\\[x=\\frac{1}{2}at^2\\]得\\(a=2\\,\\mathrm{m/s^2}\\)。步骤2：由\\(F=ma\\)得恒力\\(F=4\\,\\mathrm{N}\\)，撤力瞬间\\(v=at=8\\,\\mathrm{m/s}\\)。步骤3：粗糙面摩擦加速度大小\\(\\mu g=2\\,\\mathrm{m/s^2}\\)。步骤4：由\\(0-v^2=2as\\)得滑行距离\\(s=16\\,\\mathrm{m}\\)。结论：恒力4 N、撤力速度8 m/s、滑行16 m。"),
                topic("PT-02", "PHYSICS", "动量与能量综合", "质量为1 kg的滑块A以6 m/s向右运动，与静止的2 kg滑块B发生完全非弹性碰撞，二者随后一起压缩水平轻弹簧。若弹簧劲度系数为300 N/m，地面光滑，求共同速度和最大压缩量。", "力学>动量>动量守恒", 3,
                        "步骤1：碰撞时间短且水平方向外力冲量为零，动量守恒，1×6=(1+2)v，得v=2 m/s。步骤2：碰后到最大压缩过程中机械能守恒，(1/2)×3×2²=(1/2)×300x²。步骤3：解得x=0.20 m。碰撞本身有机械能损失，不能把碰前动能直接等同于弹性势能。"),
                topic("PT-03", "PHYSICS", "电路故障分析", "某实验电路由电源、开关、滑动变阻器、电流表和小灯泡串联组成，电压表并联在灯泡两端。闭合开关后灯泡不亮，电流表示数为零，电压表示数接近电源电压。请判断最可能的故障位置，并说明如何用一次导线检查进一步确认。", "电磁学>恒定电流>闭合电路", 2,
                        "步骤1：电流为零说明串联回路断路。步骤2：电压表跨在灯泡两端且读数接近电源电压，表明灯泡两端承受了几乎全部电源电压，因此断路最可能发生在灯泡或其接线处。步骤3：用完好导线短接灯泡两端；若电流表出现示数，可确认灯泡支路断路。检查时应先断电接线，避免带电改接。"),
                topic("PT-04", "PHYSICS", "测加速度实验", "用纸带和打点计时器研究小车匀加速运动。相邻计数点间时间均为0.10 s，连续四段位移依次为4.2 cm、5.0 cm、5.8 cm、6.6 cm。说明判断匀加速的依据，计算加速度，并写出减小随机误差的一种方法。", "物理实验>数据处理>不确定度与图像", 2,
                        "步骤1：等时间间隔内相邻位移差均为0.8 cm，符合匀变速运动的逐差特征。步骤2：由Δx=aT²，a=0.008/0.10²=0.80 m/s²。步骤3：可采用多段逐差后取平均，或作v-t图线求斜率，避免只用一组数据。读数时统一估读位数并检查计数点间隔。"),
                topic("PT-05", "PHYSICS", "电磁感应综合", "一根长0.50 m的导体棒在磁感应强度0.80 T的匀强磁场中，以4.0 m/s垂直切割磁感线。导轨总电阻为0.40 Ω，不计其他电阻。求感应电动势、电流和导体棒所受安培力，并说明外力做功与电热的关系。", "电磁学>电磁感应>法拉第定律", 3,
                        "步骤1：动生电动势E=BLv=0.80×0.50×4.0=1.6 V。步骤2：闭合回路电流I=E/R=4.0 A。步骤3：安培力F=BIL=0.80×4.0×0.50=1.6 N，方向阻碍相对运动。步骤4：匀速时外力功率Fv=6.4 W，与电热功率I²R=6.4 W相等，体现能量守恒。"),
                topic("PT-06", "PHYSICS", "光学实验设计", "用激光、半圆形玻璃砖、量角器和白纸测定玻璃折射率。请给出光路布置、需要记录的量、计算关系，并说明为什么让光线从半圆形玻璃砖的圆心射向弧面。", "光学>几何光学与波动光学>折射与干涉", 2,
                        "步骤1：让光线从空气经平直面进入玻璃，标出入射线和折射线，测入射角i与折射角r。步骤2：多次改变i，计算n=sin i/sin r并取平均，或作sin i-sin r图线求斜率。步骤3：折射线从圆心射向弧面时沿半径入射，出射处入射角为零，不再发生方向偏折，从而只分析平直界面的折射。"),

                topic("CT-01", "CHEMISTRY", "无机流程分析", "以含\\(\\mathrm{Fe^{2+}}\\)、\\(\\mathrm{Cu^{2+}}\\)的酸性废液为原料回收铜并制备\\(\\mathrm{Fe_2O_3}\\)。流程依次包括加入铁粉、过滤、向滤液通入氧化剂、调节pH沉淀铁、灼烧。说明各步骤目的，写出关键离子反应，并指出调pH时不能过高的原因。", "无机化学>金属及其化合物>铁及其化合物", 3,
                        "步骤1：铁粉置换铜离子：\\[\\mathrm{Fe+Cu^{2+}\\rightarrow Fe^{2+}+Cu}\\]过滤得到铜。步骤2：将\\(\\mathrm{Fe^{2+}}\\)氧化为\\(\\mathrm{Fe^{3+}}\\)，便于形成\\(\\mathrm{Fe(OH)_3}\\)沉淀。步骤3：调pH使\\(\\mathrm{Fe^{3+}+3OH^-\\rightarrow Fe(OH)_3\\downarrow}\\)，过滤后灼烧得到\\(\\mathrm{Fe_2O_3}\\)。pH过高会增加其他金属氢氧化物共沉淀或引入过量碱，降低产品纯度。"),
                topic("CT-02", "CHEMISTRY", "气体制备实验", "设计实验室制取并收集纯净干燥氯气的装置流程。说明发生反应、除去HCl和水蒸气的方法、收集方法及尾气处理，并指出各洗气瓶的先后顺序。", "化学实验>实验方法>分离检验与安全", 3,
                        "步骤1：用浓盐酸与二氧化锰加热制氯气，MnO₂+4HCl(浓)=MnCl₂+Cl₂↑+2H₂O。步骤2：混合气先通过饱和食盐水除HCl，再通过浓硫酸干燥；顺序不能颠倒，否则后续水洗会重新带入水蒸气。步骤3：氯气密度大且能溶于水，用向上排空气法收集。步骤4：尾气用碱液吸收，防止有毒气体逸出。"),
                topic("CT-03", "CHEMISTRY", "滴定计算", "用0.1000 mol/L NaOH标准液测定20.00 mL未知盐酸浓度。三次有效滴定体积为18.42、18.38、18.40 mL。计算盐酸浓度，并分析滴定管尖嘴起初有气泡、终点时气泡消失会造成的误差方向。", "化学反应原理>水溶液>酸碱与pH", 2,
                        "步骤1：三次数据接近，平均体积为18.40 mL。步骤2：HCl与NaOH按1∶1反应，c(HCl)=0.1000×18.40/20.00=0.09200 mol/L。步骤3：若起初尖嘴有气泡而终点消失，读出的体积包含填充尖嘴的体积，记录的耗碱量偏大，因此计算所得盐酸浓度偏高。"),
                topic("CT-04", "CHEMISTRY", "化学平衡探究", "某温度下反应N₂O₄(g)⇌2NO₂(g)达到平衡。缩小容器体积后观察到气体颜色先加深后逐渐变浅但仍比原来深。分别解释瞬时变化、平衡移动方向和最终颜色。", "化学反应原理>化学平衡>平衡移动", 2,
                        "步骤1：压缩瞬间各气体浓度均增大，棕色NO₂浓度立即增大，所以颜色先加深。步骤2：增压使平衡向气体物质的量较少的N₂O₄方向移动，消耗部分NO₂，颜色随后变浅。步骤3：新平衡体积更小，尽管NO₂的物质的量减少，其浓度通常仍高于原平衡，故最终颜色仍较深。"),
                topic("CT-05", "CHEMISTRY", "电化学综合", "用惰性电极电解CuSO₄溶液一段时间，阴极析出3.2 g铜。计算转移电子的物质的量，并说明阳极产物、溶液酸碱性变化；若改用铜作阳极，结果有何不同？", "化学反应原理>电化学>原电池与电解池", 3,
                        "步骤1：n(Cu)=3.2/64=0.050 mol，阴极Cu²⁺+2e⁻=Cu，因此转移电子0.100 mol。步骤2：惰性阳极上水失电子生成O₂和H⁺，溶液酸性增强。步骤3：若用铜阳极，则Cu-2e⁻=Cu²⁺，阳极铜溶解补充铜离子；理想情况下溶液Cu²⁺浓度和酸碱性变化较小。"),
                topic("CT-06", "CHEMISTRY", "有机合成路线", "以乙烯为主要有机原料，设计制备乙酸乙酯的反应路线。写出各步反应类型、必要条件和酯化反应方程式，并说明提高酯化产率的两种方法。", "有机化学基础>烃及其衍生物>官能团与反应", 2,
                        "步骤1：乙烯与水在催化条件下加成生成乙醇。步骤2：部分乙醇经催化氧化先生成乙醛，再氧化为乙酸。步骤3：乙酸与乙醇在浓硫酸、加热条件下发生可逆酯化：\\[\\mathrm{CH_3COOH+C_2H_5OH\\rightleftharpoons CH_3COOC_2H_5+H_2O}\\]可使用某一反应物过量或及时移去水或酯，使平衡向生成物方向移动。"),

                topic("BT-01", "BIOLOGY", "遗传概率分析", "豌豆的高茎\\(D\\)对矮茎\\(d\\)显性，圆粒\\(R\\)对皱粒\\(r\\)显性，两对基因独立遗传。\\(DdRr\\)个体自交，求后代中矮茎圆粒的概率，并说明如何从表现型为高茎圆粒的后代中鉴定纯合子。", "遗传与进化>遗传规律>分离定律", 3,
                        "步骤1：矮茎\\(dd\\)的概率为\\(\\frac{1}{4}\\)，圆粒\\(R_\\)的概率为\\(\\frac{3}{4}\\)。步骤2：独立遗传时两事件概率相乘，矮茎圆粒概率为\\(\\frac{3}{16}\\)。步骤3：鉴定高茎圆粒个体可分别与\\(ddrr\\)测交；若后代在两性状上均不发生分离，支持其为\\(DDRR\\)，若出现隐性性状则说明相应基因座为杂合。实际鉴定需足够后代数量。"),
                topic("BT-02", "BIOLOGY", "光合作用材料分析", "将同种植物置于适宜温度下，逐步提高光照强度并测定净光合速率，曲线先上升后趋于平台。解释低光、高光两个阶段的限制因素，并设计一个实验判断平台期是否受CO₂浓度限制。", "分子与细胞>细胞代谢>光合作用", 2,
                        "步骤1：低光阶段光反应供能不足，光照增强使ATP和NADPH供应增加，净光合速率上升。步骤2：平台期光不再是主要限制，CO₂浓度、温度或酶活性等可能成为限制因素。步骤3：在相同温度和平台光照下设置不同CO₂浓度，其他条件一致；若提高CO₂后净光合速率继续上升，说明原平台受CO₂限制。"),
                topic("BT-03", "BIOLOGY", "酶实验设计", "设计实验探究pH对唾液淀粉酶活性的影响。要求说明自变量、因变量、主要控制变量、检测方法和为什么不能用斐林试剂直接在反应过程中连续检测。", "生物实验>科学探究>变量控制与数据分析", 2,
                        "步骤1：设置一系列pH缓冲液，自变量为pH；各组酶量、淀粉浓度、温度和反应时间保持一致。步骤2：因变量可用相同时间后剩余淀粉量表示，用碘液显色深浅比较，或终止反应后测产物。步骤3：斐林试剂检测还原糖需要水浴加热，高温会改变酶活性并破坏原反应条件，因此不能在反应过程中连续加入检测。"),
                topic("BT-04", "BIOLOGY", "神经—体液调节", "人从温暖室内进入寒冷环境后，体温调节系统会发生变化。按感受、调节中枢、传出途径和效应器说明主要过程，并解释为什么长时间寒冷时甲状腺激素水平会上升。", "稳态与调节>生命活动调节>神经调节", 2,
                        "步骤1：皮肤和体内温度感受器感受温度下降，信息传入下丘脑体温调节中枢。步骤2：神经调节使皮肤血管收缩、骨骼肌战栗，减少散热并增加产热。步骤3：下丘脑—垂体—甲状腺轴被激活，甲状腺激素增加，促进细胞代谢和产热。神经调节起效快，激素调节较慢但作用较持久。"),
                topic("BT-05", "BIOLOGY", "生态系统材料题", "某湖泊因生活污水输入出现藻类暴发，随后鱼类大量死亡。请用物质循环、能量流动和溶解氧变化解释过程，并提出两项针对源头和生态恢复的措施。", "生物与环境>生态系统>能量流动与物质循环", 3,
                        "步骤1：污水带入氮、磷等无机盐，促进藻类过度繁殖。步骤2：藻类死亡后，分解者大量分解有机物并消耗溶解氧；夜间藻类和其他生物呼吸也耗氧，导致水体缺氧，鱼类死亡。步骤3：源头应削减污水中的氮磷排放；恢复方面可清除部分底泥、重建水生植物和合理食物网，并持续监测水质，不能只临时增氧。"),
                topic("BT-06", "BIOLOGY", "基因工程实验", "科研人员计划把抗虫基因导入植物细胞并筛选稳定表达植株。按目的基因获得、载体构建、导入、筛选鉴定和安全评价说明基本流程，并区分PCR检测与抗虫性状检测的证据。", "生物技术>现代生物工程>基因工程与细胞工程", 3,
                        "步骤1：获得目的基因，与具有标记基因和复制元件的载体连接形成重组DNA。步骤2：通过农杆菌等方法导入植物细胞，利用选择培养基筛选转化细胞，再经组织培养获得植株。步骤3：PCR只能证明目标序列存在，转录或蛋白检测说明表达，抗虫接种实验才直接评价性状。步骤4：还需考察遗传稳定性、非靶标生物影响和基因漂移风险。")
        );
    }

    private static TopicQuestion topic(String key, String subject, String title, String stem,
            String knowledgePath, int difficulty, String analysis) {
        return new TopicQuestion(key, subject, title, stem, knowledgePath, difficulty, analysis);
    }

    record TopicQuestion(String key, String subject, String title, String stem, String knowledgePath,
                         int difficulty, String analysis) {
    }
}
